import 'dart:io';
import 'package:code_builder/code_builder.dart' as cb;
import 'package:dart_style/dart_style.dart';
import 'package:path/path.dart' as p;

/// Generates `documents.dart` — a file with parsed `DocumentNode` constants
/// for every `.graphql` file in a directory.
///
/// ```dart
/// // data/datasources/product/graphql/documents.dart
/// // GENERATED — DO NOT EDIT BY HAND
/// final getProductDocument = gql(r'''...''');
/// final addItemToOrderDocument = gql(r'''...''');
/// ```
///
/// This file is **regenerated** on every `zfa build` and **never edited by hand**.
class DocumentsDartGenerator {
  DocumentsDartGenerator();
  static final _formatter = DartFormatter(
    languageVersion: DartFormatter.latestLanguageVersion,
  );

  /// Scan [graphqlDir] for `.graphql` files and generate `documents.dart`.
  String generate({required String graphqlDir, required String outputPath}) {
    final dir = Directory(graphqlDir);
    if (!dir.existsSync()) {
      throw StateError('GraphQL directory does not exist: $graphqlDir');
    }

    final documentVars = <cb.Field>[];

    for (final entity in dir.listSync(recursive: true)) {
      if (entity is! File) continue;
      if (!entity.path.endsWith('.graphql')) continue;

      final fileName = p.basenameWithoutExtension(entity.path);
      final varName = '${_camelCase(fileName)}Document';
      final content = entity.readAsStringSync();

      // Skip unvalidated files (they have a header comment)
      final cleanContent = content
          .split('\n')
          .where((line) => !line.startsWith('#'))
          .join('\n')
          .trim();

      documentVars.add(
        cb.Field((f) {
          f
            ..name = varName
            ..modifier = cb.FieldModifier.final$
            ..type = cb.refer('DocumentNode')
            ..assignment = cb.refer('gql').call([
              cb.literalString(cleanContent, raw: true),
            ]).code;
        }),
      );
    }

    final library = cb.Library((b) {
      b.directives.add(
        cb.Directive.import('package:gql/ast.dart', show: ['DocumentNode']),
      );
      b.directives.add(
        cb.Directive.import('package:gql/language.dart', show: ['gql']),
      );

      b.body.add(
        cb.Code(
          '// GENERATED CODE — DO NOT EDIT BY HAND\n'
          '// Generated by zfa gql plugin from .graphql files in ${p.basename(graphqlDir)}/\n'
          '// Regenerated on every `zfa build`\n',
        ),
      );

      for (final field in documentVars) {
        b.body.add(field);
      }
    });

    final emitter = cb.DartEmitter();
    final raw = library.accept(emitter).toString();
    return _formatter.format(raw);
  }

  /// Generate and write the file.
  void generateAndWrite({
    required String graphqlDir,
    required String outputPath,
  }) {
    final code = generate(graphqlDir: graphqlDir, outputPath: outputPath);
    final file = File(outputPath);
    file.createSync(recursive: true);
    file.writeAsStringSync(code);
  }

  String _camelCase(String name) {
    final parts = name.split(RegExp(r'[_\-]'));
    return parts.first +
        parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
  }
}
